style.css:
/* Rosy Dreams — All Websites */
/* i really want this to be global */

/* swap these colours if you want */
:root {
  --my-rose: #c58f98;
  --my-deep-rose: #a96f7b;
  --my-cream: #fff3ef;
  --my-text: #513b40;
}

/* dusty rose background */
html,
body {
  background-color: var(--my-rose) !important;
  color: var(--my-text) !important;
}

/* soft pink links */
a {
  color: var(--my-deep-rose) !important;
}

/* pretty rounded images */
img,
video {
  border-radius: 12px !important;
}

/* softer text selection */
::selection {
  background: #e9b9c1 !important;
  color: #513b40 !important;
}

/* gentle scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-thumb {
  background: var(--my-deep-rose) !important;
  border-radius: 20px !important;
}

::-webkit-scrollbar-track {
  background: var(--my-cream) !important;
}
